def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    proposals = []

    # Look for nearly solid rectangles of each non-background color.
    for color in set(v for row in grid for v in row):
        if color == bg:
            continue
        pref = [[0] * (w + 1) for _ in range(h + 1)]
        for r in range(h):
            for c in range(w):
                pref[r + 1][c + 1] = (
                    pref[r][c + 1] + pref[r + 1][c] - pref[r][c]
                    + (grid[r][c] == color)
                )

        for r0 in range(h):
            for r1 in range(r0, h):
                for c0 in range(w):
                    for c1 in range(c0, w):
                        area = (r1 - r0 + 1) * (c1 - c0 + 1)
                        if area < 4:
                            continue
                        count = (pref[r1 + 1][c1 + 1] - pref[r0][c1 + 1]
                                 - pref[r1 + 1][c0] + pref[r0][c0])
                        if count * 5 >= area * 4:
                            proposals.append((count / area, area, color,
                                              r0, r1, c0, c1))

    # Keep the best-supported rectangle color at each cell. This fills
    # isolated corruptions inside rectangles and discards stray pixels.
    out = [[bg] * w for _ in range(h)]
    quality = [[(-1.0, -1)] * w for _ in range(h)]
    for density, area, color, r0, r1, c0, c1 in proposals:
        score = (density, area)
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                if score > quality[r][c]:
                    quality[r][c] = score
                    out[r][c] = color

    return out
